mapper.select:
SELECT m.id, m.title, m.content, m.type, m.sender_id AS senderId, m.sender_name AS senderName, m.send_time AS sendTime, m.create_time AS createTime, mu.id AS receiveId, mu.read_status AS readStatus, mu.read_time AS readTime FROM sys_message_user mu INNER JOIN sys_message m ON m.id = mu.message_id AND m.deleted = 0 AND m.status = 1 WHERE mu.deleted = 0 AND mu.receiver_id = #{receiverId}
AND mu.read_status = #{readStatus}
AND m.title LIKE CONCAT('%', #{title}, '%')
ORDER BY mu.read_status ASC, m.send_time DESC
